snippets.css:
/* Compact lists */
[data-part="card"] {
  padding: 0.75rem;
}
[data-part="section-head"] {
  margin-bottom: 0.5rem;
}
[data-part="media-tile-title"] {
  font-size: 0.8125rem;
  line-height: 1.2;
}

/* No decorations: the dot frame and halftone prints */
:root,
[data-theme] {
  --dn-frit-opacity: 0;
}
